"""Render empirical tables from sealed scores, including a matched independent review."""
import collections,statistics
from setup29 import D,P,h,sha,read,save,Path
from score29 import DIMS,PAST,ARMS
A=["B","H","T","G","O"]
LABEL={"B":"Чистый BM25","H":"Гибрид BM25 + E5","T":"Гибрид с учётом времени","G":"Время + направленная связь","O":"Авторские old/new (диагностика)"}
def rate(x):return f"{100*x:.1f}".replace(".",",")
def f(x):return str(x).replace(".",",")
def main():
    s=read(D/"score.json");au=read(D/"judge-audit.json");cs=read(D/"candidate-score.json")["summary"];before=read(D/"prefix-input-seal.json")
    blocks=[];line=blocks.append
    line("# Память об изменившемся состоянии пользователя. Пилот STALE")
    line("В восьми сценариях проверили, помогает ли второе связанное свидетельство применить обновление в ответе. На один сценарий приходится 50 датированных сессий и три исходных вопроса. Отбор фиксирован хешем внутри двух типов сценариев. Четыре случая обновляют один атрибут, четыре требуют перенести изменение на зависимое состояние. Вся коллекция STALE включает 400 сценариев. [Статья и критерии](https://arxiv.org/html/2605.06527v1#S3)")
    line("### Ответы об актуальном состоянии")
    ss=s["scores"];h=ss["native"]["H"]["approved"];t=ss["native"]["T"]["approved"];g=ss["native"]["G"]["approved"]
    delta=s["paired"]["G-T"]["native"]["pass_proxy"];lo,hi=delta["bootstrap95"]
    line(f"На 24 исходных вопросах локальный судья принял {g} ответов с направленной связью G, {t} при выборе по времени T и {h} при гибридном поиске H. По основному сравнению G–T разность составила {rate(delta['delta'])} п.п., парный процентильный 95%-й интервал по восьми сценариям [{rate(lo)} … {rate(hi)}]. Число исходов, где G выиграл, проиграл или получил ту же оценку, — {delta['wins']}, {delta['losses']} и {delta['ties']} соответственно. При восьми кластерах интервал иллюстрирует неопределённость пилота.")
    out=["| Условие | SR /8 | PR /8 | IPA /8 | Всего /24 | Старый источник /24 | Новый источник /24 | Оба источника /24 | Обе полные строки /24 |",
         "|---|---:|---:|---:|---:|---:|---:|---:|---:|"]
    for a in A:
        n=ss["native"][a];values=[*[ss[m][a]["approved"] for m in DIMS],n["approved"],n["old_source"],n["new_source"],n["both_sources"],n["both_literal"]]
        out.append("| "+" | ".join([LABEL[a],*["—" if v is None else str(v) for v in values]])+" |")
    line("\n".join(out))
    line("Все три обычные политики выбирают две разные сессии и передают датированные выдержки одинаковой длины. H объединяет BM25 и E5 через reciprocal rank fusion. T дополнительно учитывает хронологию. G удерживает тот же первый адрес, предпочитает более позднего кандидата из оставшихся семи, учитывает близость между первым и вторым отрывками. В O ридер сразу видит авторскую пару в короткой форме. Для B измеряли только адреса. «Обе полные строки» означает буквальное присутствие полных авторских цитат после нормализации Unicode, регистра и пунктуации. Парафраз может передавать смысл при нулевой буквальной метрике.")
    sources=s["literal_whole_source"];line(f"В полных пользовательских репликах размеченных источников исходные буквальные строки до усечения обнаружены для {sum(v['old'] for v in sources.values())}/8 старых и {sum(v['new'] for v in sources.values())}/8 новых свидетельств. Баллы по типам T1/T2 в порядке H/T/G/O составляют "+", ".join(k+" — "+"/".join(str(s["strata"][k][a]["approved"]) for a in ARMS)+" из 12" for k in sorted(s["strata"]))+".")
    line("### Потолок при фиксированном наборе кандидатов")
    line(f"В доступных восьми кандидатах обычного гибридного поиска старый источник содержался для {cs['old_in_pool']}/24 запросов, новый для {cs['new_in_pool']}/24, оба для {cs['both_in_pool']}/24. При обязательном сохранении первого кандидата обе сессии всё ещё достижимы для {cs['both_possible_given_anchor']}/24. После ограничения направления у G теоретический потолок по паре составляет {cs['both_possible_after_direction']}/24. Эти потолки вычислены оценщиком по закрытой разметке после фиксации всех кандидатов. Они относятся к идентичности сессий. Найденный адрес не гарантирует передачу самой реплики и корректное использование в ответе.")
    ev=read(D/"evidence-application.json")
    detail=[]
    for a in ("H","T","G"):
        z=ev["native_buckets"].get(a+"/source/both",{"accepted":0,"n":0})
        detail.append(f"{a} — {z['accepted']} из {z['n']}")
    line("Когда действительно доставлены оба источника, доля принятых ответов составляет "+", ".join(detail)+". Условные группы зависят от трудности и темы запросов. Для причинного вывода о пользе пары нужен эксперимент, в котором передача второго свидетельства рандомизируется внутри одного и того же задания.")
    line("### Историческая применимость")
    line("К каждому прямому вопросу добавили отдельную проверку о том, что пользователь ранее сообщал по теме до указанной даты. Сначала доступны только сессии исторического префикса. Затем задан тот же вопрос к архиву после появления обновления. В позднем архиве H может открыть будущую относительно вопроса сессию. В T/G дата ограничивает допустимые источники. В O для физического префикса дано только старое высказывание, для позднего архива даны оба. Для проверки достаточно верно пересказать предыдущее сообщение. Истечение временного состояния допускается.")
    out=["| Условие | В префиксе верно /8 | Поздний архив верно /8 | Ошибочно отозван прошлый факт, префикс /8 | То же, архив /8 | Старый источник в архиве /8 | Более новый источник /8 |",
         "|---|---:|---:|---:|---:|---:|---:|"]
    for a in ARMS:
        early=ss["past_prefix"][a];late=ss["past_full"][a]
        arr=[early["approved"],late["approved"],early["grades"].get("R",0),late["grades"].get("R",0),late["old_source"],late["new_source"]]
        out.append("| "+" | ".join([LABEL[a],*["—" if v is None else str(v) for v in arr]])+" |")
    line("\n".join(out));line("Полные четырёхкатегориальные исходы V (верный исторический факт), R (ретроактивное отрицание или подстановка более позднего состояния), U (неуверенность), X (прочая ошибка) сохранены по вопросу. Дата среза сконструирована между двумя авторскими источниками. Эти исторические задачи входят только в дополнительную оценку.")
    line("### Проверка оценщика и затрат")
    v=au["native"];u=au["historical"];line(f"Анонимная стратифицированная проверка с другим агентом Codex совпала с локальным Qwen по {v['agree']}/{v['n']} авторским заданиям и {u['agree']}/{u['n']} историческим при разметке по четырём категориям. Всего совпало {au['all']['agree']}/{au['all']['n']}. При бинаризации исторического ответа в «верно / остальное» совпало {au['historical_correct_binary']}/8. Для {len(au['inconsistent_exact_groups'])} из {au['repeated_exact_groups']} групп одинакового ответа на одинаковый вопрос у локального судьи встречаются разные решения. Тройки ответов для исходных вопросов подаются ему совместно, согласно структуре авторской инструкции. Независимый агент оценивает отдельный ответ. Все пять расхождений на авторских вопросах — положительные оценки локального судьи, отклонённые независимым рецензентом. В двух исторических расхождениях локальный судья поставил R, независимый рецензент — V. По этому срезу нельзя надёжно интерпретировать относительный ранг методов либо частоту ошибочного отзыва прошлого. Независимый рецензент — второй ИИ. Человеческая оценка составила бы отдельную проверку.")
    costs=s["costs"];line("На 40 логических вопросах фактические токены полного входа/выхода и число обрезанных по лимиту ответов составили "+", ".join(a+" — "+f"{costs[a]['input_sum']}/{costs[a]['output_sum']} ({costs[a]['capped']} обрезано)" for a in ARMS)+". Для каждой из 40 троек слепых входов число Qwen-токенов обоих датированных фрагментов совпадает по позициям. На 34 из 40 заданий длины полного промпта по трём методам совпали. На остальных шести максимальное расхождение при разборе в llama.cpp составило один токен. Отдельно учитывается стоимость оценщика.")
    actor=read(D/"effective-actor-forecast-seal.json");judge=read(D/"judge-forecast-seal.json")
    line(f"Ридер и локальный оценщик — Qwen3-4B-Instruct-2507 Q4_K_M на CPU, два потока, temperature 0, один независимый контекст на запрос. На 160 назначений приходятся {actor['active']} уникальных действующих входов и {actor['physical']} реально рассчитанных с учётом первоначальной версии. У оценщика {judge['unique']} уникальных запросов, {judge['failed']} ошибок выполнения. Обычные источники нарезаны окнами 144 нативных токена; для всех политик берутся только слова пользователя. Модель, формат ответа судьи и бюджет отличаются от штатного Gemini-3.1-flash-lite и условий CUPMem на полном STALE. Перенос чисел в лидерборд требует воспроизведения официального протокола. [Эксперименты авторов](https://arxiv.org/html/2605.06527v1#S4)")
    line(f"До чтения ответов мы проверили полную изоляцию физического префикса. При исключении будущих записей до int8-инференса E5 у {before['changed_early']}/8 ранних и {before['changed_retro']}/8 поздних исторических задач изменились исходные адреса или выравнивание выдач. Пакетное квантование могло менять соседние оценки даже при фильтрации по времени перед ранжированием. Для итоговой оценки использованы физически изолированные префиксы и {before['unique_extra']} дополнительно зафиксированных входа. Первоначальные хеши и логи сохранили. Основные 24 исходные задачи оцениваются по первоначально зарегистрированным прогнозам.")
    line("### Вывод для дальнейшей проверки")
    line("Дополнительная направленная связь сохранила результат T по доставке пары (7/24) и по буквальной доставке обоих утверждений (1/24). При этом все авторские высказывания имеются в полных исходных репликах. Следующая проверяемая гипотеза касается выбора конкретной реплики внутри уже правильно найденных двух сессий. Следует фиксировать их адреса и сравнить выбор спана по вопросу, по связи с первой репликой и по сильному независимому reranker при одинаковом бюджете. Дополнительный эксперимент с привилегированным выбором размеченных реплик внутри тех же заранее отобранных сессий отделит потерю при вырезании текста от ошибки читателя. Следующую панель стоит отделить по сценариям, применить официальный скорер, дать независимую оценку части ответов людьми и заранее учесть расхождения между оценщиками.")
    (D/"REPORT_RU.md").write_text("\n\n".join(blocks)+"\n",encoding="utf8")
if __name__=="__main__":main()
